async function phoneAuthEmail(phone){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('kpyx-phone-auth:v1:'+phone));const id=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('').slice(0,40);return id+'@login.kpyx.invalid'}function inviteLink(){const origin=/^(localhost|127\.)/.test(location.hostname)?'https://kpyx.fun':location.origin;return origin+'/register?ref='+encodeURIComponent(inviteCode())}
