function abidjanPromo(){const now=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Abidjan',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now),vals={};parts.forEach(p=>vals[p.type]=p.value);const hour=Number(vals.hour),active=hour>=11&&hour<16,targetHour=active?16:(hour<11?11:35),target=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+(targetHour===35?1:0),targetHour===35?11:targetHour,0,0)),left=Math.max(0,Math.ceil((target-now)/60000));return {active,left:Math.floor(left/60)+' h '+String(left%60).padStart(2,'0')+' min'}}
