function digitalServiceCard(p){return '<article class="digital-offer-card" data-brand="'+p.brand+'"><div class="digital-logo-frame"><img src="'+A+IMG[p.logo]+'" alt="Logo '+p.name+'" loading="lazy"></div><div class="digital-offer-copy"><span class="digital-offer-label">LOT INDIVIDUEL · 10 ACCÈS</span><h2>'+p.name+'</h2><p>'+p.subtitle+'</p><div class="digital-card-price"><strong data-individual-price="'+p.id+'">'+money(p.price)+' F</strong><small>prix fixe · 10 accès</small></div><div class="digital-quantity"><span>Nombre de lots</span><div><button type="button" data-offer-step="-1" data-service="'+p.id+'" aria-label="Retirer un lot">−</button><b data-offer-count="'+p.id+'">1</b><button type="button" data-offer-step="1" data-service="'+p.id+'" aria-label="Ajouter un lot">+</button></div></div><button class="button soft digital-select-button" disabled title="Le stock et la livraison des accès ne sont pas encore configurés">Stock à charger</button></div></article>'}
function digitalBundleCard(pack){const services=pack.items.map(id=>DIGITAL_PRODUCTS.find(p=>p.id===id)),sum=services.reduce((n,p)=>n+p.price,0),images=services.map(p=>'<span class="bundle-logo"><img src="'+A+IMG[p.logo]+'" alt="'+p.name+'" loading="lazy"></span>').join(''),names=services.map(p=>p.name).join(' + ');return '<article class="bundle-pack-card" data-pack-card="'+pack.id+'"><div class="bundle-pack-top"><span class="bundle-pack-badge">'+pack.badge+'</span><span class="bundle-pack-discount">−'+pack.discount+' %</span></div><h3>'+pack.name+'</h3><p class="bundle-pack-services">'+names+'</p><div class="bundle-pack-logos">'+images+'</div><div class="bundle-quantity"><span>Lots de 10 accès par service</span><div><button type="button" data-bundle-step="-1" data-pack="'+pack.id+'" aria-label="Retirer un lot">−</button><b data-bundle-count="'+pack.id+'">1</b><button type="button" data-bundle-step="1" data-pack="'+pack.id+'" aria-label="Ajouter un lot">+</button></div></div><div class="bundle-pack-prices"><strong class="bundle-total-price" data-pack-retail="'+pack.id+'">'+money(sum)+' F</strong></div><button class="button primary bundle-download" disabled title="Le stock et la livraison des accès ne sont pas encore configurés">Stock à charger</button></article>'}
function digitalResaleContent(){const bundles=DIGITAL_PACKS.map(digitalBundleCard).join(''),individuals=DIGITAL_PRODUCTS.map(digitalServiceCard).join('');return '<div class="digital-resale-content"><header class="resale-store-header"><div><span class="eyebrow">BOUTIQUE · ACHAT ET REVENTE</span><h1>Choisis tes packs <em>à revendre</em></h1><p>Chaque lot contient 10 accès par service. Les offres s’ouvriront dès que le stock réel et la remise sécurisée des accès seront configurés.</p></div><div class="resale-flow"><span><b>1</b> Achète</span><i>→</i><span><b>2</b> Récupère tes accès</span><i>→</i><span><b>3</b> Revends</span></div></header>'+digitalPromoBanner()+'<div class="digital-section-heading resale-packs-heading"><span><small>OFFRES DISPONIBLES</small><h2>Packs Duo, Triple, 4 et Maxi</h2></span><span class="section-count">Prix calculés automatiquement</span></div><div class="digital-bundle-grid">'+bundles+'</div><p class="digital-access-note">Chaque filleul qualifié donne 1 000 FCFA de réduction sur les packs (3 maximum), après sa première recharge confirmée de 3 000 FCFA minimum. Les offres individuelles sont exclues.</p><div class="digital-section-heading individual-heading"><span><small>OFFRES À L’UNITÉ</small><h2>Un service à la fois</h2></span><span class="section-count">10 accès par lot</span></div><div class="digital-offer-grid">'+individuals+'</div></div>'}
function qualifiedReferralCount(){return Math.min(3,Math.max(0,Math.floor(Number(window.KPYX_ACCOUNT?.qualifiedReferralCount||0))))}
function updateDigitalPricing(){const promo=abidjanPromo(),referralCredit=qualifiedReferralCount()*1000;document.querySelectorAll('[data-promo-status]').forEach(el=>el.textContent=promo.active?'PROMO · prix calculés automatiquement':'Prix calculé automatiquement');document.querySelectorAll('[data-promo-copy]').forEach(el=>el.textContent=promo.active?'Remise de 2 % appliquée au montant de chaque pack.':'Promotion de 2 % chaque jour, de 11 h à 16 h.');document.querySelectorAll('[data-promo-banner]').forEach(el=>el.classList.toggle('is-live',promo.active));DIGITAL_PRODUCTS.forEach(p=>document.querySelectorAll('[data-individual-price="'+p.id+'"]').forEach(el=>{const card=el.closest('.digital-offer-card'),count=Number(card.querySelector('[data-offer-count]').textContent||1);el.textContent=money(p.price*count)+' F';const pay=card.querySelector('.digital-select-button');if(pay){pay.dataset.totalPrice=p.price*count;pay.textContent='Payer '+money(p.price*count)+' F →'}}));DIGITAL_PACKS.forEach(pack=>{const card=document.querySelector('[data-pack-card="'+pack.id+'"]');if(!card)return;const qty=Number(card.querySelector('[data-bundle-count]').textContent||1),base=pack.items.reduce((n,id)=>n+DIGITAL_PRODUCTS.find(p=>p.id===id).price,0)*qty,rate=promo.active?pack.discount:0,cost=Math.max(0,Math.round(base*(100-rate)/100)-referralCredit);card.classList.toggle('is-promo',promo.active);card.querySelector('.bundle-pack-discount').textContent=promo.active?'PROMO':'';card.querySelector('[data-pack-retail]').textContent=money(cost)+' F';const pay=card.querySelector('.bundle-download');if(pay){pay.dataset.totalPrice=cost;pay.textContent='Payer '+money(cost)+' F · recevoir mes accès →'}})}
function startDigitalPurchase(amount){toast('Paiement de '+money(Number(amount||0))+' FCFA indisponible : aucun prestataire n’est connecté. Aucun accès n’est remis.')}
function money(n){return n.toLocaleString('fr-FR').replace(/\u202f/g,' ')}
function vipCatalogContent(){const bands=[['Espaces essentiels','L1–L3',0,3],['Espaces Pro','L4–L6',3,6],['Espaces Signature','L7–L8',6,8]];return `<div class="products-sticky"><div class="app-page-bar"><strong>Forfaits d’adhésion</strong><button class="owned-plans" data-go="my-products">${NAV_SVG.key} Mes forfaits <b>0</b></button></div><div class="products-title"><span><small>8 FORFAITS</small><h1>Forfaits <em>d’adhésion</em></h1></span></div><p class="products-sub">Chaque forfait est un étage de l’immeuble. Choisissez-en un et des crédits arrivent sur votre solde toutes les 24 heures.</p><div class="howto"><div>${img('plans')}<small>01</small><span>Choisissez un forfait adapté à votre budget</span></div><div>${img('hourglass')}<small>02</small><span>Les crédits arrivent toutes les 24 heures</span></div><div>${img('cashout')}<small>03</small><span>Retirez vers Mobile Money ou votre banque</span></div></div><div class="chips price-filters">${['Tous','≤ 2 000','2 000 - 10 000','10 000 - 50 000','50 000 et plus'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-filter="${i}">${x}</button>`).join('')}</div></div>${bands.map(([heading,levels,start,end])=>`<section class="plan-band" data-band="${start}"><div class="band-heading"><h2>${heading}</h2><small>${levels}</small></div><div class="product-list">${PLANS.slice(start,end).map(([name,space,desc,price,daily,total,im,level],i)=>{const idx=start+i;const unavailable=idx>=4;return `<button class="actual-plan" data-plan-index="${idx}" data-range="${price<=2000?1:price<=10000?2:price<=50000?3:4}"><div class="plan-photo ${im}">${img(im)}<span class="level">${level}&nbsp; ${space}</span>${unavailable?'<span class="soon">Pas encore ouvert</span>':''}</div><div class="plan-card-content"><div class="plan-card-heading"><strong>${name}</strong><span class="round-arrow">${NAV_SVG.arrow}</span></div><p>${desc}</p><div class="plan-specs"><span><small>Prix</small><b>${money(price)} FCFA</b></span><span><small>Crédit quotidien</small><b class="credit">+${money(daily)} FCFA</b></span><span><small>Durée</small><b>90 jours</b></span></div><div class="plan-total">Total des crédits <b>${money(total)} FCFA</b></div></div></button>`}).join('')}</div></section>`).join('')}`}
function products(){return dash("<div class='products-mode-shell'><section class='plan-mode-panel catalog-tabs'><div class='plan-mode-copy'><span class='eyebrow'>CATALOGUE KPYX</span><p>Choisis ton espace : forfaits VIP ou packs de comptes à revendre.</p></div><div class='plan-mode-switch' role='group' aria-label='Mode des offres'><button class='plan-mode' data-plan-mode='purchase' aria-pressed='false'>Achat · VIP</button><button class='plan-mode active' data-plan-mode='resale' aria-pressed='true'>Packs à revendre</button></div></section><section class='vip-purchase-content' hidden>"+vipCatalogContent()+"</section><section class='digital-resale-panel'>"+digitalResaleContent()+"</section></div>")}
function team(){const invite=[1000,2000,6000,12000,20000,60000],active=[5,10,30,60,100,300],network=[5000,10000,30000,50000,100000,300000,500000],volume=[500000,1000000,3000000,5000000,10000000,30000000,50000000];const tiers=(title,note,rewards,targets,label)=>`<section class="reward-group"><button class="reward-heading" data-toggle="${title==='Objectifs d’invitation'?'invite':'network'}"><span><strong>${title}</strong><small>${note}</small></span><b>0 / ${rewards.length}</b><i>⌄</i></button><div class="reward-list collapsed" data-rewards="${title==='Objectifs d’invitation'?'invite':'network'}">${rewards.map((reward,i)=>`<article class="reward-card"><div class="reward-top"><span class="tier-number">${i+1}</span><span class="tier-name">Palier ${i+1}</span><strong>${money(reward)} FCFA</strong><span class="locked">♙ &nbsp;Non atteint</span></div><div class="reward-target"><span>${label}</span><b>0&nbsp; / &nbsp;${money(targets[i])}${title==='Objectifs du réseau'?'':' membres'}</b></div><div class="progress-track"><i style="width:0%"></i></div></article>`).join('')}</div><button class="show-tiers" data-toggle="${title==='Objectifs d’invitation'?'invite':'network'}">Afficher les ${rewards.length} paliers　⌄</button></section>`;return dash(`<div class="team-sticky"><strong>Mon réseau</strong></div><div class="team-head"><div class="eyebrow">0 DANS VOTRE RÉSEAU</div><h1>Mon <em>réseau</em></h1><img src="${A+IMG.network}" alt="" class="team-illustration"><p>Invitez des personnes avec votre code et réclamez les récompenses que vous débloquez.</p></div><section class="invite-card"><div class="invite-brand"><b>KPYX</b><span>PASS D'INVITATION</span><button data-action="copy-link" aria-label="Copier le lien">♧</button></div><div class="invite-code"><span>Code d'invitation</span><strong>${inviteCode()}</strong><button data-action="copy-invite" aria-label="Copier le code">⧉</button></div><div class="invite-link"><span>${inviteLink()}</span><button data-action="copy-link" aria-label="Copier le lien">↗</button></div><div class="commission-levels"><div><span class="level-dot"></span><small>1er</small><b>−1 000 F</b><span>Filleul qualifié</span></div><div><span class="level-dot"></span><small>2e</small><b>−1 000 F</b><span>Filleul qualifié</span></div><div><span class="level-dot"></span><small>3e</small><b>−1 000 F</b><span>Filleul qualifié</span></div></div></section><button class="bonus-info" data-action="toggle-bonus"><span class="bonus-icon">i</span><span><strong>Bonus de parrainage</strong><small>1 000 FCFA par filleul qualifié · 3 maximum</small></span><b>⌃</b></button><div class="bonus-detail"><p>Chacun des 3 premiers filleuls débloque <b>1 000 FCFA de réduction</b> sur les packs après une première recharge confirmée d’au moins <b>3 000 FCFA</b>.</p><p>La remise s’applique aux packs Duo, Triple, de 4 et Maxi. Elle ne s’applique pas aux offres individuelles.</p><p>La qualification doit être confirmée par le système de paiement avant que la remise soit appliquée.</p><div class="bonus-actions"><button class="button primary small" data-action="share-invite">Partager</button><button class="button soft small" data-action="copy-link">Copier le lien</button></div></div><section class="how-network"><div class="how-network-title"><div><small>COMMENT ÇA MARCHE ?</small><h2>Comment fonctionne le parrainage</h2><p>Partagez votre lien. Un filleul est qualifié après sa première recharge confirmée de 3 000 FCFA minimum.</p></div><button data-action="toggle-guide" aria-label="Fermer">×</button></div><div class="guide-steps" id="guide-steps">${[['invite','1','Partagez votre code d’invitation avec vos amis'],['growth','2','Vos amis s’inscrivent et souscrivent leur premier forfait'],['sparkle','3','Vos commissions de parrainage arrivent automatiquement']].map(([im,n,t])=>`<div class="guide-step">${img(im)}<span>${n}</span><p>${t}</p></div>`).join('')}</div><div class="guide-rates"><p>Après une première recharge confirmée ≥ 3 000 FCFA <b>−1 000 FCFA sur les packs</b></p><p>Maximum <b>3 filleuls qualifiés</b>, soit 3 000 FCFA de réduction</p><p>Valable sur les packs ; <b>pas sur les achats individuels</b></p></div></section><section class="network-overview"><h2>Votre réseau en un coup d'œil</h2><article class="commission-card"><div><small>COMMISSIONS DU RÉSEAU</small><strong>0 FCFA</strong><span>Cette semaine　·　+0 FCFA</span></div><button data-go="fund-flow">Détails ↗</button></article><div class="network-stats"><article><strong>0</strong><span>Total des membres</span></article><article><strong>0</strong><span>Membres actifs</span></article><article><strong>0 FCFA</strong><span>Commissions totales</span></article><article><strong>0 FCFA</strong><span>Souscriptions du réseau</span></article></div></section><section class="rewards-section"><h2>Récompenses</h2>${tiers('Objectifs d’invitation','Invitez des amis directs qui souscrivent un forfait. Chaque palier ne peut être réclamé qu’une fois.',invite,active,'Membres actifs')}${tiers('Objectifs du réseau','Total des souscriptions de forfaits de votre réseau de niveaux 1 à 3. Chaque palier ne peut être réclamé qu’une fois.',network,volume,'Souscriptions du réseau')}</section><section class="network-members"><h2>Membres du réseau</h2><div class="member-level-tabs" role="tablist" aria-label="Membres du réseau">${['L1','L2','L3'].map((x,i)=>`<button role="tab" aria-selected="${i===0}" class="${i===0?'active':''}" data-level="${x}">${x}</button>`).join('')}</div><p class="level-caption">Niveau 1 (direct)</p><div class="member-empty">${img('door')}<p>Aucun membre pour le moment. Partagez votre code d'invitation pour développer votre réseau.</p></div></section>`)}
function community(){return dash(`${pageHead('Communauté','Les nouvelles de votre communauté KPYX.',button('Créer une publication','community-create','primary small'))}<div class="chips"><button class="chip active">Tout</button><button class="chip">Membres</button><button class="chip">Actualités</button></div><section class="glass-card big-empty">${img('community')}<h3>Bienvenue dans la communauté</h3><p>Les publications et actualités des membres apparaîtront ici.</p><button class="text-button" data-action="notice">Découvrir l’espace communauté</button></section>`)}
function listPage(){let rows={'my-products':[['keycard','Mes forfaits','Vos adhésions actives apparaîtront ici.','Aucun forfait actif'],['plans','Découvrir les forfaits','Explorez les espaces et options disponibles.','']],'fund-flow':[['receipt','Mouvements du compte','Recharges, retraits et activités du compte.','Aucune activité récente'],['topup','Recharger mon solde','Ajoutez des fonds à votre compte membre.','']],'messages':[['inbox','Boîte de réception','Retrouvez les messages et annonces de KPYX.','Vous êtes à jour'], ''], 'withdraw-history':[['cashout','Retraits','Suivez vos demandes de retrait.','Aucun retrait pour le moment']],'recharge-history':[['topup','Recharges','Suivez vos opérations de recharge.','Aucune recharge pour le moment']]}[route]||[];let r=rows[0];return dash(`${pageHead(TITLES[route]||'Historique')}<section class="panel big-empty">${img(r[0])}<h3>${r[3]}</h3><p>${r[2]}</p>${r[1].includes('forfait')?button('Voir les forfaits →','go:products','primary small'):''}</section>`)}
function profile(){const rows=[['HISTORIQUE',[['receipt','Historique des recharges','recharge-history'],['cashout','Historique des retraits','withdraw-history']]],['ACTIVITÉS',[['checkin','Présence quotidienne','check-in']]],['SERVICES',[['help','Assistance','support'],['globe','À propos de KPYX','about']]],['PARAMÈTRES',[['shield','Changer le mot de passe','change-password'],['profile','Modifier le profil','edit-profile'],['phone','Obtenir l’application','app-download']]]];return dash(`<section class="account-hero"><div class="account-avatar">U</div><div class="account-identity"><h1>Utilisateur</h1><p>+225 •• ••• ••••</p></div><button class="account-edit" data-go="edit-profile" aria-label="Modifier le profil"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 5 3 3L8 19l-4 1 1-4Z"/><path d="m14 7 3 3"/></svg></button></section><section class="account-balance"><div class="account-balance-top"><span>Solde　<button class="text-button" data-action="toggle-balance">${eyeIcon()}</button></span><button class="active-plans" data-go="my-products"><b>0</b> Forfaits actifs</button></div><div class="account-amount"><strong id="balance">${money(balanceAmount)}</strong><span>FCFA</span></div><div class="account-actions"><button data-go="recharge" class="account-recharge">↙　Recharge</button><button data-go="withdraw">↗　Retrait</button><button data-go="fund-flow" aria-label="Historique">▤</button></div></section><div class="account-shortcuts">${[['keycard','Mes forfaits','my-products'],['growth','Activité','fund-flow'],['card','Compte de paiement','bank-card'],['inbox','Messages','messages']].map(([im,label,path])=>`<button data-go="${path}">${img(im)}<span>${label}</span></button>`).join('')}</div>${rows.map(([heading,items])=>`<section class="account-menu-group"><h2>${heading}</h2><div>${items.map(([im,label,path])=>`<button class="account-row" data-go="${path}">${img(im)}<span>${label}</span><b>›</b></button>`).join('')}</div></section>`).join('')}<button class="account-logout" data-action="logout">Se déconnecter</button>`)}
function operation(kind){const rec=kind==='recharge',min=rec?3000:1200,max=90071992547409,presets=rec?[3000,8000,15000,30000,60000,150000]:[1200,2000,3000,5000,10000],title=rec?'Recharge':'Retrait';const methods=[['wave','Wave'],['orange','Orange Money'],['mtn','MTN Mobile Money'],['moov','Moov Money'],['djamo','Djamo']];return dash(`<div class="wallet-head"><button class="support-back" data-go="profile" aria-label="Retour">←</button><div><span class="eyebrow">PORTEFEUILLE</span><h1>${title}</h1></div><button class="wallet-history" data-go="${rec?'recharge-history':'withdraw-history'}">Historique ↗</button></div><form class="glass-card form-panel wallet-form" data-form="operation" data-kind="${kind}"><div class="wallet-balance"><span>${rec?'Solde du membre':'Disponible pour un retrait'}</span><strong id="balance">${money(balanceAmount)} <small>FCFA</small></strong><button type="button" data-action="toggle-balance">${eyeIcon()}</button></div><div class="wallet-input-heading"><label for="wallet-amount">${rec?'Montant':'Montant du retrait'}</label><span>Min. ${money(min)} · Max. ${money(max)} FCFA</span></div><div class="wallet-amount-input"><input id="wallet-amount" name="amount" class="input" type="number" min="${min}" max="${max}" step="100" placeholder="Saisissez le montant" required><b>FCFA</b></div><div class="preset-title">Montants rapides</div><div class="chips wallet-presets">${presets.map(v=>`<button class="chip" type="button" data-amount="${v}">${money(v)}</button>`).join('')}</div><div class="wallet-section-title">${rec?'Choisissez votre mode de paiement':'Destination du retrait'}</div><div class="payment-methods payment-method-list">${methods.map(([id,label],i)=>`<button type="button" class="payment-method ${i===0?'active':''}" data-method="${id}" aria-pressed="${i===0}"><i>${id==='wave'?'◉':id==='orange'?'◌':id==='mtn'?'●':id==='moov'?'◆':'▣'}</i><span><b>${label}</b><small>${rec?'Jèko':'Traitement manuel'}</small></span><b>${i===0?'✓':'○'}</b></button>`).join('')}</div>${rec?`<input type="hidden" name="method" value="wave"><div class="wallet-note"><b>Recharge sécurisée</b><span>Montant minimum : 3 000 FCFA. Votre solde et la roue sont mis à jour après confirmation du paiement.</span></div><div class="wallet-summary"><span>Vous allez recharger</span><strong id="wallet-summary">— FCFA</strong></div>`:`<label class="field payout-destination"><span>Numéro Mobile Money ou identifiant Djamo</span><input class="input" name="destination" type="text" autocomplete="tel" minlength="6" maxlength="80" placeholder="Ex. +225 07 00 00 00 00" required></label><input type="hidden" name="method" value="wave"><div class="withdraw-summary"><div><span>Frais de retrait (7 %)</span><b id="withdraw-fee">— FCFA</b></div><div><span>Vous recevrez</span><strong id="withdraw-net">— FCFA</strong></div></div><div class="wallet-note"><b>Retrait manuel</b><span>Votre demande reste en attente jusqu’à son traitement. Vérifiez soigneusement la destination avant validation.</span></div>`}<button class="button primary wallet-submit" type="submit">${rec?'Continuer vers le paiement':'Demander le retrait'} →</button></form>`)}
function lottery(){const prizes=[100,200,500,1000,2000,5000,10000,20000];return dash(`${pageHead('Roue de la chance','La roue se débloque après confirmation d’une recharge de 3 000 FCFA ou plus.',`<button class="owned-plans" data-go="fund-flow">Mes gains&nbsp; 0</button>`)}<section class="lottery-screen"><div class="lottery-caption">${img('wheel','lottery-source-icon')}<span class="badge">AVANTAGE ROOFTOP</span><h2>Tournez pour gagner<br><em>des lots membres</em></h2><p>Des prix en argent pour les membres · Chaque tour est gagnant</p></div><div class="wheel-status"><span class="pulse-dot"></span><span id="wheel-status">Recharge confirmée requise · 3 000 FCFA min.</span><button class="text-button" data-action="show-wheel-rules">Règles</button></div><div class="wheel-stage"><div class="wheel-pointer"><svg viewBox="0 0 24 32"><path d="M12 31 1 3a1.5 1.5 0 0 1 2-1.8L12 5l9-3.8A1.5 1.5 0 0 1 23 3Z"/></svg></div><div class="wheel-disk" id="wheel-disk"><div class="wheel-labels">${prizes.map(x=>`<span>${money(x)}</span>`).join('')}</div><div class="wheel-hub"></div></div><div class="wheel-center"></div></div><button class="button primary spin-button" data-action="spin">TOURNER</button><p class="spin-note">Tour disponible uniquement après confirmation d’une recharge de 3 000 FCFA minimum.</p><div class="lottery-inline-actions"><button data-action="show-wheel-rules">Comment jouer ?</button><button data-go="products">Choisir un forfait ↗</button></div></section><section class="lottery-ladder"><div><h2>Sur la roue</h2><p>Des prix en argent, versés sur votre portefeuille lorsque vous les réclamez.</p></div><div class="prize-grid">${prizes.slice().reverse().map((x,i)=>`<article class="prize-tile"><span>${i===0?'GAIN MAXIMAL':'LOT MEMBRE'}</span><strong>${money(x)} <small>FCFA</small></strong></article>`).join('')}</div></section><section class="panel lottery-history section"><div class="panel-title">Mes tours <span class="badge">HISTORIQUE</span></div><p>Chaque tour et son résultat apparaîtront ici.</p><div id="spin-history"><div class="big-empty">${img('wheel')}<h3>Aucun tour pour le moment</h3><p>Vos résultats de la roue apparaîtront ici.</p></div></div></section><section class="lottery-winners panel section"><div class="panel-title">Derniers gagnants <span class="live-badge"><i></i> EN DIRECT</span></div><div class="winner-row"><span class="winner-avatar">A</span><span><b>Membre KPYX</b><small>vient de tourner la roue</small></span><strong>+ 500 FCFA</strong></div><div class="winner-row"><span class="winner-avatar">K</span><span><b>Membre KPYX</b><small>a remporté un lot membre</small></span><strong>+ 1 000 FCFA</strong></div><div class="winner-row"><span class="winner-avatar">M</span><span><b>Membre KPYX</b><small>a remporté un lot membre</small></span><strong>+ 200 FCFA</strong></div></section>`)}
function giftCodePage(){return dash(`${pageHead('Code cadeau','Échangez un code contre des crédits.')}<section class="gift-code-card"><div class="gift-code-art">${img('gift')}</div><span class="eyebrow">AVANTAGE ASSISTANCE</span><h2>Saisissez votre code cadeau</h2><p>Vous avez reçu un code lors d’un événement ou de la communauté ? Saisissez-le pour ajouter le crédit à votre solde.</p><form data-form="gift-redeem"><label for="gift-code-input">Code cadeau</label><div class="gift-input-row"><input id="gift-code-input" class="input" placeholder="Saisissez le code" autocomplete="off" required><button type="button" data-action="clear-gift" aria-label="Effacer le code">×</button></div><small>Tapez ou collez le code que vous avez reçu.</small><button class="button primary" type="submit">Utiliser le code →</button></form></section><section class="gift-records panel section"><div class="panel-title">Mes codes utilisés</div><div class="big-empty">${img('gift')}<h3>Aucun code utilisé pour le moment</h3></div></section>`)}
function supportPage(){return dash(`<section class="support-page"><header class="support-head"><button class="support-back" data-go="profile" aria-label="Retour">←</button><div>${img('concierge')}<span><strong>Service d’assistance</strong><small><i></i> En ligne</small></span></div><button class="icon-button" data-action="support-info" aria-label="Informations">i</button></header><div class="support-intro"><span class="eyebrow">SERVICE D’ASSISTANCE</span><h1>Comment pouvons-nous vous aider aujourd’hui ?</h1><p>Posez vos questions sur votre adhésion, vos recharges ou vos retraits. Touchez une question rapide ci-dessous ou écrivez la vôtre.</p></div><div class="support-channel-cards"><button data-action="contact-telegram">${img('phone')}<span><strong>Telegram</strong><small>Contacter via Telegram</small></span><b>↗</b></button><button data-action="contact-whatsapp">${img('message')}<span><strong>WhatsApp</strong><small>Discuter avec l’assistance</small></span><b>↗</b></button></div><div class="support-quick"><h2>Choisissez un sujet</h2>${[['Ma recharge n’est pas arrivée','Ma recharge n’est pas arrivée'],['Où en est mon retrait ?','Où en est mon retrait ?'],['Comment fonctionnent les crédits ?','Comment fonctionnent les crédits ?'],['Commissions et tours gratuits','Commissions de parrainage et tours gratuits'],['Mon compte et compte de paiement','Mon compte et mon compte de paiement']].map(([label,value])=>`<button data-quick-question="${value}">${label}<span>›</span></button>`).join('')}</div><div class="support-chat"><div id="chat-messages"><article class="chat-message assistant"><small>Assistant IA · aujourd’hui</small><p>Bonjour ! Dites-moi ce que vous souhaitez savoir. Je peux vous aider avec votre adhésion, vos paiements ou votre compte.</p></article></div><button class="human-agent" data-action="request-human">Parler à un conseiller</button><form data-form="support-chat"><input name="message" class="input" placeholder="Écrire à l’assistance…" required><button type="submit" aria-label="Envoyer">↑</button></form></div></section>`)}
function generic(){if(route==='edit-profile')return dash(`${pageHead('Modifier le profil')}<form class="glass-card form-panel account-form" data-form="generic"><div class="change-photo"><div class="account-avatar">U</div><button type="button" data-action="notice">Changer la photo</button></div><div class="field"><label>Nom</label><input class="input" value="Utilisateur" required></div><button class="button primary" type="submit">Enregistrer</button></form>`);if(route==='change-password')return dash(`${pageHead('Changer le mot de passe')}<form class="glass-card form-panel account-form" data-form="generic"><div class="field"><label>Mot de passe actuel</label><input class="input" type="password" required></div><div class="field"><label>Nouveau mot de passe</label><input class="input" type="password" minlength="6" required></div><div class="field"><label>Confirmer le mot de passe</label><input class="input" type="password" minlength="6" required></div><button class="button primary" type="submit">Confirmer</button></form>`);if(route==='bank-card')return dash(`${pageHead('Compte de paiement','Ajoutez un compte pour recevoir vos retraits.')}<form class="glass-card form-panel account-form" data-form="payout-account"><div class="field"><label>Nom du titulaire</label><input class="input" autocomplete="name" required></div><div class="field"><label>Nom de l’établissement</label><select class="input"><option>Choisir un opérateur</option><option>Orange Money</option><option>MTN Mobile Money</option><option>Moov Money</option><option>Wave</option><option>Compte bancaire</option></select></div><div class="field"><label>Numéro de compte</label><input class="input" inputmode="numeric" placeholder="Numéro Mobile Money ou compte"></div><div class="field"><label>Numéro de téléphone</label><input class="input" type="tel" required></div><div class="wallet-note"><b>Vérifiez les informations</b><span>Le nom du titulaire doit correspondre au compte de paiement utilisé pour recevoir vos retraits.</span></div><button class="button primary" type="submit">Enregistrer le compte →</button></form>`);let titles={about:'À propos de KPYX', 'bank-card':'Moyen de paiement',support:'Assistance',tasks:'Mes tâches','check-in':'Présence quotidienne','gift-code':'Code cadeau','app-download':'Application mobile','bonus-pool':'Cagnotte bonus','notification-settings':'Notifications','forgot-password':'Mot de passe oublié'};let title=titles[route]||TITLES[route]||'Votre espace';let info={about:'Une communauté d’adhésion construite autour d’espaces de travail flexibles : des salons ouverts et bureaux dédiés jusqu’aux bureaux privés et aux espaces pour les équipes.',support:'Notre équipe est là pour vous accompagner. Retrouvez vos échanges et les réponses aux questions fréquentes.',tasks:'Les tâches disponibles pour votre compte seront affichées ici.', 'check-in':'Chaque jour, passez pour découvrir votre récompense de présence.', 'gift-code':'Saisissez un code cadeau pour l’ajouter à votre espace.', 'app-download':'Retrouvez KPYX sur votre téléphone.', 'bonus-pool':'La cagnotte bonus rassemble la communauté.', 'bank-card':'Ajoutez un compte Mobile Money ou bancaire pour recevoir vos retraits.', 'notification-settings':'Choisissez les informations que vous souhaitez recevoir.'}[route]||'Gérez les informations de votre espace membre KPYX.';let action=route==='check-in'?'Marquer ma présence':route==='gift-code'?'Utiliser mon code':route==='app-download'?'Télécharger l’application':route==='bank-card'?'Ajouter un moyen de paiement':'En savoir plus';let form=route==='gift-code'||route==='bank-card'||route==='support';return dash(`${pageHead(title)}<section class="glass-card panel" style="max-width:700px">${img(route==='check-in'?'checkin':route==='gift-code'?'gift':route==='bank-card'?'card':route==='support'?'help':'tower','')}<h2 style="font-size:21px;margin:8px 0">${title}</h2><p class="sub">${info}</p>${form?`<form data-form="generic"><div class="field"><label>${route==='gift-code'?'Code cadeau':route==='support'?'Votre message':'Nom du titulaire'}</label><input class="input" required placeholder="${route==='gift-code'?'Saisissez votre code':route==='support'?'Comment pouvons-nous vous aider ?':'Nom complet'}"></div>${route==='bank-card'?`<div class="field"><label>Numéro Mobile Money ou compte</label><input class="input" placeholder="Votre numéro de paiement" required></div>`:''}<button class="button primary" type="submit">${action} →</button></form>`:button(action,route==='about'?'notice':route==='app-download'?'notice':`do:${route}`,'primary small')}</section>`)}
function welcomeGiftAnnouncement(){return `<div class="welcome-gift-overlay" id="welcome-gift"><section class="welcome-gift-card" role="dialog" aria-modal="true" aria-labelledby="welcome-gift-title"><div class="welcome-gift-confetti" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="welcome-gift-icon">${img('gift')}</div><span class="eyebrow">CADEAU DE BIENVENUE</span><h2 id="welcome-gift-title">Félicitations !</h2><p>Votre cadeau de bienvenue a bien été reçu.</p><strong class="welcome-gift-amount">+700 FCFA</strong><button class="button primary" data-go="home">Découvrir mon espace →</button></section></div>`}
function welcomeAnnouncement(){return `<div class="announcement-backdrop" id="announcement"><section class="announcement glass-card"><header><span class="badge">BIENVENUE CHEZ KPYX</span><button class="icon-button" data-action="close-announcement" aria-label="Fermer">×</button></header><div class="announcement-copy"><p>Votre espace membre est prêt.</p><p>Découvrez les forfaits, suivez vos crédits et développez votre réseau depuis votre compte.</p><h3>Besoin d’aide ?</h3><p>Contactez l’assistance pour obtenir le canal Telegram ou WhatsApp de votre région.</p></div><div class="announcement-actions"><button class="button primary" data-action="contact-telegram">Canal Telegram</button><button class="button soft" data-action="contact-whatsapp">WhatsApp</button><button class="text-button" data-action="close-announcement">Continuer vers mon espace</button></div></section></div>`}
function updateVisibleBalance(){document.querySelectorAll('#balance').forEach(el=>{if(el.querySelector('small'))el.innerHTML=money(balanceAmount)+' <small>FCFA</small>';else el.textContent=money(balanceAmount)})}
let kpyxNotificationChannel=null;function listenKpyxNotifications(db,userId){if(kpyxNotificationChannel)db.removeChannel(kpyxNotificationChannel);kpyxNotificationChannel=db.channel('kpyx-notifications-'+userId).on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+userId},({new:n})=>toast((n.title||'Notification')+' · '+(n.body||''))).subscribe()}
async function syncKpyxAccount(){const db=window.kpyxSupabase;if(!db)return;const {data:{user}}=await db.auth.getUser();if(!user)return;const [{data:wallet},{data:credits},{data:profile}]=await Promise.all([db.from('wallets').select('balance_xof').eq('user_id',user.id).maybeSingle(),db.from('referral_credits').select('id').eq('referrer_user_id',user.id).eq('status','available'),db.from('profiles').select('referral_code').eq('id',user.id).maybeSingle()]);balanceAmount=Number(wallet?.balance_xof||0);const displayName=user.user_metadata?.display_name||((user.phone||user.user_metadata?.phone_e164)?'Membre '+(user.phone||user.user_metadata.phone_e164).slice(-4):'Membre KPYX');const accountName=document.querySelector('.account-identity h1');if(accountName)accountName.textContent=displayName;const accountPhone=document.querySelector('.account-identity p');if(accountPhone)accountPhone.textContent=user.phone||user.user_metadata?.phone_e164||'';const accountAvatar=document.querySelector('.account-avatar');if(accountAvatar)accountAvatar.textContent=displayName.trim().charAt(0).toUpperCase();const greeting=document.querySelector('.member-greeting strong');if(greeting)greeting.textContent='Bienvenue, '+displayName;window.KPYX_ACCOUNT={...(window.KPYX_ACCOUNT||{}),userId:user.id,referralCode:profile?.referral_code||null,qualifiedReferralCount:credits?.length||0};updateVisibleBalance();const codeNode=document.querySelector('.invite-code strong');if(codeNode)codeNode.textContent=inviteCode();const linkNode=document.querySelector('.invite-link span');if(linkNode)linkNode.textContent=inviteLink();if(route==='products')updateDigitalPricing();listenKpyxNotifications(db,user.id)}
async function syncKpyxCatalog(){const db=window.kpyxSupabase;if(!db)return;const [{data:products,error:pErr},{data:contents,error:cErr}]=await Promise.all([db.from('digital_products').select('id,name,category,price_xof,active').eq('active',true),db.from('pack_items').select('pack_id,product_id').order('pack_id')]);if(pErr||cErr)return;const byId=new Map((products||[]).map(p=>[p.id,p]));DIGITAL_PRODUCTS.forEach(p=>{const row=byId.get(p.id);if(row){p.name=row.name;p.price=Number(row.price_xof)}});DIGITAL_PACKS.forEach(pack=>{const items=(contents||[]).filter(row=>row.pack_id===pack.id).map(row=>row.product_id);if(items.length)pack.items=items});updateDigitalPricing()}
function showVerifiedWelcomeGift(){if(localStorage.getItem('kpyx-welcome-shown')==='1')return;localStorage.setItem('kpyx-welcome-shown','1');app.insertAdjacentHTML('beforeend',welcomeGiftAnnouncement());requestAnimationFrame(()=>document.querySelector('#welcome-gift')?.classList.add('is-visible'))}
window.addEventListener('kpyx:supabase-ready',async()=>{const db=window.kpyxSupabase;if(!db){console.error('Supabase browser client failed to load',window.kpyxSupabaseError);return}const {data:{session}}=await db.auth.getSession();if(session){await syncKpyxAccount();if(['login','register'].includes(route)){route='home';paintRoute()}}else if(!['login','register','forgot-password','about'].includes(route)){route='login';paintRoute()}if(route==='products')syncKpyxCatalog();db.auth.onAuthStateChange((event,next)=>{if(next){setTimeout(()=>syncKpyxAccount(),0)}else if(event==='SIGNED_OUT'){balanceAmount=0;window.KPYX_ACCOUNT=undefined;go('login')}})});
function render(){if(['login','register','forgot-password'].includes(route)){app.innerHTML=auth();return}let pages={home,products,team,community,profile,recharge:()=>operation('recharge'),withdraw:()=>operation('withdraw'),about:generic,'my-products':listPage,'fund-flow':listPage,messages:listPage,'withdraw-history':listPage,'recharge-history':listPage,'bank-card':generic,support:supportPage,tasks:generic,'check-in':generic,lottery,'gift-code':giftCodePage,'app-download':generic,'bonus-pool':generic,'notification-settings':generic,'edit-profile':generic,'change-password':generic,'telegram-bind':generic,'community-create':generic,'community-detail':generic};app.innerHTML=(pages[route]||home)();if(route==='products'){updateDigitalPricing();if(window.kpyxSupabase)syncKpyxCatalog();clearInterval(digitalPromoTimer);digitalPromoTimer=setInterval(updateDigitalPricing,30000)}else clearInterval(digitalPromoTimer);if(route==='team')revealNetworkSections();if(route==='home'&&!localStorage.getItem('kpyx-announcement-dismissed')){app.insertAdjacentHTML('beforeend',welcomeAnnouncement());requestAnimationFrame(()=>document.querySelector('#announcement')?.classList.add('visible'))}}
document.addEventListener('click',e=>{const spin=e.target.closest('[data-action="spin"]');if(spin){toast('Aucun tour confirmé : une recharge de 3 000 FCFA minimum doit être vérifiée par le service.');return;const disk=document.querySelector('#wheel-disk');if(!disk||spin.disabled)return;const prizes=[100,200,500,1000,2000,5000,10000,20000],index=Math.floor(Math.random()*prizes.length),prize=prizes[index];let currentAngle=wheelRotation;try{const transform=getComputedStyle(disk).transform;if(transform&&transform!=='none'){const matrix=new DOMMatrixReadOnly(transform);currentAngle=(Math.atan2(matrix.b,matrix.a)*180/Math.PI+360)%360}}catch{}wheelRotation=currentAngle;const turn=1800+((360-index*45-(currentAngle%360)+360)%360),targetAngle=currentAngle+turn;wheelRotation=targetAngle;disk.classList.add('is-spinning');spin.disabled=true;spin.textContent='La roue tourne…';const spinAnimation=disk.animate([{transform:`rotate(${currentAngle}deg)`},{transform:`rotate(${targetAngle}deg)`}],{duration:4100,easing:'cubic-bezier(.08,.68,.12,1)',fill:'forwards'});setTimeout(()=>{spin.disabled=false;spin.textContent='TOURNER';disk.style.setProperty('--rest-angle',wheelRotation+'deg');spinAnimation.cancel();disk.classList.remove('is-spinning');const history=document.querySelector('#spin-history');if(history)history.innerHTML=`<div class="winner-row"><span class="winner-avatar">W</span><span><b>Votre tour</b><small>à l’instant</small></span><strong>+ ${money(prize)} FCFA</strong></div>`;document.querySelector('.wheel-result')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="announcement-backdrop visible wheel-result"><section class="announcement wheel-result-card"><span class="badge">VOUS AVEZ GAGNÉ</span><h2>${money(prize)} FCFA</h2><p>Le gain apparaîtra dans vos récompenses après validation.</p><button class="button primary" data-action="claim-prize">OK</button></section></div>`)},4100);return}const plan=e.target.closest('[data-plan-index]');if(plan){const p=PLANS[Number(plan.dataset.planIndex)];document.querySelector('.detail-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="announcement-backdrop visible detail-modal"><section class="announcement plan-detail"><button class="icon-button detail-close" data-action="close-detail">×</button><img class="detail-photo" src="${A+IMG[p[6]]}" alt="${p[1]}"><div class="detail-body"><span class="badge">${p[7]} · ${p[1]}</span><h2>${p[0]}</h2><p>${p[2]}</p><div class="plan-specs"><span><small>Prix</small><b>${money(p[3])} FCFA</b></span><span><small>Crédit quotidien</small><b class="credit">+${money(p[4])} FCFA</b></span><span><small>Durée</small><b>90 jours</b></span></div><div class="plan-total">Total des crédits <b>${money(p[5])} FCFA</b></div><button class="button primary detail-join" data-action="join-plan" data-plan-price="${p[3]}">${Number(plan.dataset.planIndex)>=4?'Pas encore ouvert':'Souscrire à ce forfait'} →</button></div></section></div>`);return}const target=e.target.closest('[data-go],[data-action],[data-filter],[data-amount],[data-toggle],[data-level],[data-plan-mode],[data-offer-step],[data-bundle-step]');if(!target)return;if(target.dataset.offerStep){const card=target.closest('.digital-offer-card'),count=card.querySelector('[data-offer-count]');count.textContent=Math.min(99,Math.max(1,Number(count.textContent)+Number(target.dataset.offerStep)));updateDigitalPricing();return}if(target.dataset.bundleStep){const card=target.closest('[data-pack-card]'),count=card.querySelector('[data-bundle-count]');count.textContent=Math.min(99,Math.max(1,Number(count.textContent)+Number(target.dataset.bundleStep)));updateDigitalPricing();return}if(target.dataset.toggle){const kind=target.dataset.toggle;const box=document.querySelector('[data-rewards="'+kind+'"]');if(box){box.classList.toggle('collapsed');const group=target.closest('.reward-group');const toggle=group?.querySelector('.show-tiers');if(toggle)toggle.innerHTML=box.classList.contains('collapsed')?'Afficher les '+box.querySelectorAll('.reward-card').length+' paliers　⌄':'Voir moins　⌃'}return}if(target.dataset.level){document.querySelectorAll('[data-level]').forEach(x=>{x.classList.toggle('active',x===target);x.setAttribute('aria-selected',x===target?'true':'false')});const n=target.dataset.level.slice(1);document.querySelector('.level-caption').textContent='Niveau '+n+(n==='1'?' (direct)':'');return}if(target.dataset.go){e.preventDefault();go(target.dataset.go);return}if(target.dataset.amount){const input=document.querySelector('[data-form="operation"] input[type=number]');if(input)input.value=target.dataset.amount;target.classList.add('active');return}if(target.dataset.planMode){const resale=target.dataset.planMode==='resale';document.querySelectorAll('[data-plan-mode]').forEach(tab=>{const active=tab.dataset.planMode===(resale?'resale':'purchase');tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active))});document.querySelector('.vip-purchase-content').hidden=resale;document.querySelector('.digital-resale-panel').hidden=!resale;updateDigitalPricing();return}if(target.dataset.filter){return}const act=target.dataset.action||'';if(act==='download-access-manifest'){startDigitalPurchase(target.dataset.totalPrice);return}else if(act==='choose-digital-service'){const builder=[...document.querySelectorAll('[data-pack-builder]')].find(el=>el.dataset.packBuilder===target.dataset.mode),check=[...builder.querySelectorAll('[data-pack-toggle]')].find(el=>el.dataset.service===target.dataset.service),card=target.closest('.digital-offer-card'),count=card.querySelector('[data-service-count]'),packCount=[...builder.querySelectorAll('[data-pack-count]')].find(el=>el.dataset.service===target.dataset.service);check.checked=true;packCount.textContent=count.textContent;updateDigitalPricing();builder.scrollIntoView({behavior:'smooth',block:'center'});return}else if(act==='close-announcement'){document.querySelector('#announcement')?.classList.remove('visible');localStorage.setItem('wework-demo-announcement-dismissed','1');setTimeout(()=>document.querySelector('#announcement')?.remove(),300)}else if(act==='close-detail'){document.querySelector('.detail-modal')?.remove()}else if(act==='join-plan'){const cost=Number(target.dataset.planPrice||0);document.querySelector('.detail-modal')?.remove();if(cost>500){toast('Solde insuffisant. Rechargez votre portefeuille pour souscrire.');go('recharge')}else toast('Souscription préparée dans cette démonstration.')} else if(act.startsWith('go:'))go(act.slice(3));else if(act==='toggle-balance'){balanceVisible=!balanceVisible;document.querySelector('#balance').textContent=balanceVisible?money(balanceAmount):'••••'}else if(act==='copy-invite'){navigator.clipboard?.writeText(inviteCode()).then(()=>toast('Code d’invitation copié')).catch(()=>toast('Code : '+inviteCode()))||toast('Code : '+inviteCode())}else if(act==='toggle-bonus'){const box=document.querySelector('.bonus-detail');box.hidden=!box.hidden;target.querySelector('b').textContent=box.hidden?'⌄':'⌃'}else if(act==='copy-link'){navigator.clipboard?.writeText(inviteLink()).then(()=>toast('Lien de parrainage copié')).catch(()=>toast('Lien : '+inviteLink()))||toast('Lien : '+inviteLink())}else if(act==='toggle-guide'){const box=target.closest('.how-network');if(box)box.hidden=true}else if(act==='share-invite'){if(navigator.share)navigator.share({title:'Rejoindre KPYX',text:'Découvrez KPYX et ses espaces membres.'}).catch(()=>{});else toast('Partage bientôt disponible sur cet appareil.')}else if(act==='logout'){const db=window.kpyxSupabase;if(db)db.auth.signOut().then(()=>go('login'));else go('login')}else if(act==='notice'){toast('Cette section est disponible dans l’espace membre.')}else if(act.startsWith('plan:')){toast('Connectez-vous pour consulter les tarifs de ce forfait.')}else if(act.startsWith('do:')){toast('Cette fonction sera disponible dans votre espace membre.')}});
