document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="register"],[data-form="login"]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{const db=window.kpyxSupabase;if(!db){toast('Connexion Supabase indisponible. Rechargez la page et réessayez.');return}const password=form.querySelector('[name="password"]')?.value||'',raw=form.querySelector('[name="phone"]')?.value.trim()||'',digits=raw.replace(/\D/g,''),prefix=form.querySelector('[name="country-code"]')?.value||'+225',phone=raw.startsWith('+')?'+'+digits:prefix+digits.replace(/^0/,'');if(!/^\+\d{8,15}$/.test(phone)){toast('Saisissez un numéro avec son indicatif et au moins 8 chiffres.');return}const email=await phoneAuthEmail(phone);if(form.dataset.form==='register'){const passwords=form.querySelectorAll('[type="password"]');if(passwords.length>1&&passwords[1].value!==password){toast('Les deux mots de passe ne correspondent pas.');return}const referral=referralFromUrl()||form.querySelector('.invite-input')?.value.trim()||'';const {data,error}=await db.auth.signUp({email,password,options:{data:{phone_e164:phone,referral_code:referral||null}}});if(error){toast(/already registered|user exists/i.test(error.message)?'Ce numéro a déjà un compte. Connectez-vous.':'Impossible de créer le compte. Vérifiez le numéro et le mot de passe.');return}if(!data.session){toast('Connexion non activée : l’authentification e-mail sans confirmation doit être active.');return}await syncKpyxAccount();route='home';paintRoute();showVerifiedWelcomeGift();toast('Compte créé et connecté.');return}const {error}=await db.auth.signInWithPassword({email,password});if(error){toast(/invalid login credentials|user not found/i.test(error.message)?'Mot de passe ou numéro incorrect.':'Connexion impossible. Vérifiez vos informations.');return}await syncKpyxAccount();route='home';paintRoute();toast('Bienvenue dans votre espace membre.')}catch(error){console.error('KPYX authentication failed:',error?.message||'unknown error');toast('Impossible de terminer l’authentification. Réessayez.')}finally{submit.disabled=false}},true);
function revealNetworkSections(){const nodes=[...app.querySelectorAll('.team-head,.invite-card,.bonus-info,.how-network,.network-overview,.commission-card,.network-stats article,.rewards-section,.reward-group,.reward-card,.network-members,.member-empty,.guide-step,.commission-levels>div')];nodes.forEach((node,index)=>{node.classList.add('network-reveal');node.style.setProperty('--reveal-delay',Math.min(index%6,5)*55+'ms')});if(!('IntersectionObserver'in window)){nodes.forEach(node=>node.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -4% 0px'});nodes.forEach(node=>observer.observe(node))}
