function eyeIcon(){return '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.6-6 10-6 10 6 10 6-3.6 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="3"/></svg>'}

function updateWalletPreview(){const form=document.querySelector('.wallet-form');if(!form)return;const amount=Number(form.querySelector('[name=amount]')?.value||0);if(form.dataset.kind==='recharge'){const value=document.querySelector('#wallet-summary');if(value)value.textContent=amount?money(amount)+' FCFA':'— FCFA'}else{const fee=document.querySelector('#withdraw-fee'),net=document.querySelector('#withdraw-net');if(fee)fee.textContent=amount?money(Math.round(amount*.07))+' FCFA':'— FCFA';if(net)net.textContent=amount?money(amount-Math.round(amount*.07))+' FCFA':'— FCFA'}}
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form="operation"]');if(!form)return;e.preventDefault();const db=window.kpyxSupabase;if(!db){toast('Service de compte indisponible. Réessayez plus tard.');return}const {data:{session}}=await db.auth.getSession();if(!session){go('login');return}const amount=Number(form.querySelector('[name=amount]').value),method=form.querySelector('[name=method]').value,endpoint=form.dataset.kind==='recharge'?'/api/jeko/create-payment':'/api/withdrawals',payload=form.dataset.kind==='recharge'?{amount,paymentMethod:method}:{amount,method,account:form.querySelector('[name=destination]').value.trim()},submit=form.querySelector('[type=submit]');submit.disabled=true;try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok)throw new Error(result.error||'Opération impossible.');if(form.dataset.kind==='recharge'){location.assign(result.redirectUrl);return}await syncKpyxAccount();toast('Demande envoyée. Elle est en attente de traitement.');go('withdraw-history')}catch(error){toast(error.message)}finally{submit.disabled=false}},true);
document.addEventListener('input',e=>{if(e.target.matches('#wallet-amount'))updateWalletPreview()});
document.addEventListener('click',e=>{const quick=e.target.closest('[data-quick-question]');if(quick){const box=document.querySelector('#chat-messages');if(box){const user=document.createElement('article');user.className='chat-message user';const p=document.createElement('p');p.textContent=quick.dataset.quickQuestion;user.append(p);const reply=document.createElement('article');reply.className='chat-message assistant';reply.innerHTML='<small>Assistant IA</small>';const answer=document.createElement('p');answer.textContent='Je vérifie les informations disponibles. Pour le suivi de votre compte, demandez à parler à un conseiller.';reply.append(answer);box.append(user,reply);reply.scrollIntoView({behavior:'smooth',block:'nearest'})}return}const method=e.target.closest('[data-method]');if(method){document.querySelectorAll('[data-method]').forEach(x=>{x.classList.toggle('active',x===method);x.setAttribute('aria-pressed',String(x===method));const mark=x.querySelector(':scope > b:last-child');if(mark)mark.textContent=x===method?'✓':'○'});const hidden=document.querySelector('.wallet-form [name=method]');if(hidden)hidden.value=method.dataset.method;return}const action=e.target.closest('[data-action]')?.dataset.action;if(action==='clear-gift'){const input=document.querySelector('#gift-code-input');if(input)input.value=''}else if(action==='claim-prize'){document.querySelector('.wheel-result')?.remove();toast('Résultat conservé dans cet aperçu local.')}else if(action==='show-wheel-rules'){document.querySelector('.wheel-rules-modal')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="announcement-backdrop visible wheel-rules-modal"><section class="announcement wheel-result-card"><button class="icon-button detail-close" data-action="close-rules">×</button><span class="badge">RÈGLES</span><h2>Règles de la roue de la chance</h2><div class="announcement-copy"><p>Souscrivez un forfait pour débloquer des tours. Un tour est aussi gagné lorsqu’un ami invité souscrit son premier forfait.</p><p>Certains gains peuvent nécessiter des amis actifs. Chaque résultat apparaît dans votre historique.</p></div><button class="button primary" data-action="close-rules">Compris</button></section></div>')}else if(action==='close-rules'){document.querySelector('.wheel-rules-modal')?.remove()}else if(action==='contact-telegram'||action==='contact-whatsapp'||action==='request-human'){if(route!=='support'){go('support')}else toast('Le canal officiel de votre région doit être fourni par le service.')}});
