document.addEventListener('submit',e=>{const form=e.target.closest('[data-form="gift-redeem"]');if(form){e.preventDefault();toast('Code introuvable dans cette démonstration. Vérifiez-le et réessayez.');return}const payout=e.target.closest('[data-form="payout-account"]');if(payout){e.preventDefault();toast('Ajoutez votre destination de paiement depuis la demande de retrait.');return}const chat=e.target.closest('[data-form="support-chat"]');if(chat){e.preventDefault();const input=chat.querySelector('[name=message]'),message=input.value.trim(),box=document.querySelector('#chat-messages');if(!message||!box)return;const item=document.createElement('article');item.className='chat-message user';const p=document.createElement('p');p.textContent=message;item.append(p);box.append(item);input.value='';setTimeout(()=>{const reply=document.createElement('article');reply.className='chat-message assistant';const text=document.createElement('p');text.textContent='Merci pour votre message. Demandez à parler à un conseiller pour le suivi de votre compte.';reply.append(text);box.append(reply);reply.scrollIntoView({behavior:'smooth',block:'nearest'})},550)}});

